import{_ as a,c as t,o as n,a2 as r}from"./chunks/framework.mqLGQ42V.js";const v=JSON.parse('{"title":"事件概览 (Events Overview) - Rive 编辑器","description":"事件 (Events) 如果你正在使用 数据绑定 (Data Binding)，你可以直接从代码中监听触发器或值变化，而无需额外使用“事件”。","frontmatter":{"title":"事件概览 (Events Overview) - Rive 编辑器","description":"事件 (Events) 如果你正在使用 数据绑定 (Data Binding)，你可以直接从代码中监听触发器或值变化，而无需额外使用“事件”。","head":[["meta",{"name":"keywords","content":"Rive, Rive 中文文档, Rive 编辑器, 事件概览"}]]},"headers":[],"relativePath":"editor/events.md","filePath":"editor/events.md","lastUpdated":1774867914000}'),o={name:"editor/events.md"};function i(s,e,l,p,c,d){return n(),t("div",null,[...e[0]||(e[0]=[r('<p>事件 (Events)</p><h1 id="事件概览-events-overview" tabindex="-1">事件概览 (Events Overview) <a class="header-anchor" href="#事件概览-events-overview" aria-label="Permalink to &quot;事件概览 (Events Overview)&quot;">​</a></h1><p>如果你正在使用 <a href="/docs/editor/data-binding/overview">数据绑定 (Data Binding)</a>，你可以直接从代码中监听触发器或值变化，而无需额外使用“事件”。</p><p><strong>事件</strong>是一种在精确时刻向运行时代码发送信号的方法。它们通过传递有用信息来增强设计师与开发者之间的沟通。利用事件，我们可以触发诸如：打开网页（URL）、播放音效、显示特定的 HTML 元素，或者任何可以通过代码实现的逻辑。</p><p>在设计阶段和运行时协调好 Rive 事件，对于在应用、游戏等场景下的成功集成至关重要。</p><h2 id="​-创建事件-creating-an-event" tabindex="-1"><a href="#creating-an-event">​</a> 创建事件 (Creating an Event) <a class="header-anchor" href="#​-创建事件-creating-an-event" aria-label="Permalink to &quot;[​](#creating-an-event) 创建事件 (Creating an Event)&quot;">​</a></h2><p>要创建事件，请使用位于工具栏中的 <strong>事件工具 (Events tool)</strong>。激活工具后，点击画板上的任意位置即可添加一个新事件。</p><blockquote><p><em>[原文档演示图由于官方服务器迁移已失效]</em> (描述: 添加新事件示例) 你会发现事件会同时显示在舞台画板上和层级面板 (Hierarchy) 中。</p></blockquote><h2 id="​-配置事件-configuring-an-event" tabindex="-1"><a href="#configuring-an-event">​</a> 配置事件 (Configuring an Event) <a class="header-anchor" href="#​-配置事件-configuring-an-event" aria-label="Permalink to &quot;[​](#configuring-an-event) 配置事件 (Configuring an Event)&quot;">​</a></h2><p>添加事件后，我们需要在检查器 (Inspector) 中进行配置。</p><blockquote><p><em>[原文档演示图由于官方服务器迁移已失效]</em> (描述: 检查器中的事件配置)</p></blockquote><h3 id="​-名称-name" tabindex="-1"><a href="#name">​</a> 名称 (Name) <a class="header-anchor" href="#​-名称-name" aria-label="Permalink to &quot;[​](#name) 名称 (Name)&quot;">​</a></h3><p>名称字段用于给事件指定唯一标识。这非常重要，因为在运行时，开发者需要根据这个名称来挂载代码逻辑。</p><blockquote><p><em>[原文档演示图由于官方服务器迁移已失效]</em> (描述: 重命名事件) 你也可以直接在画板上点击名称进行修改。</p></blockquote><h3 id="​-类型-type" tabindex="-1"><a href="#type">​</a> 类型 (Type) <a class="header-anchor" href="#​-类型-type" aria-label="Permalink to &quot;[​](#type) 类型 (Type)&quot;">​</a></h3><p>类型下拉菜单允许你在这两种事件类型间切换：<strong>General (通用)</strong> 和 <strong>URL</strong>。</p><h3 id="​-属性-properties" tabindex="-1"><a href="#properties">​</a> 属性 (Properties) <a class="header-anchor" href="#​-属性-properties" aria-label="Permalink to &quot;[​](#properties) 属性 (Properties)&quot;">​</a></h3><p>属性允许你向运行时传递额外的信息。例如，你可能想传递一个音频文件的名称，以便在事件上报时播放对应的声音，或者传递一些用于数据分析的元数据。 点击属性旁边的“加号”按钮即可添加新属性。</p><blockquote><p><em>[原文档演示图由于官方服务器迁移已失效]</em> (描述: 添加新属性) 你需要为属性重命名，并选择其跟踪的值类型（数字、布尔值或字符串）。</p></blockquote><h3 id="​-url" tabindex="-1"><a href="#url">​</a> URL <a class="header-anchor" href="#​-url" aria-label="Permalink to &quot;[​](#url) URL&quot;">​</a></h3><p>当选择 <code>Open URL</code> 事件时，会出现额外的配置：</p><blockquote><p><em>[原文档演示图由于官方服务器迁移已失效]</em> (描述: URL 配置示例)</p></blockquote><ul><li><strong>URL</strong>：在文本框中输入目标网址（确保包含 <code>http://</code> 或 <code>https://</code>）。</li><li><strong>Target (目标)</strong>：告诉浏览器在哪里打开 URL。 <ul><li><code>Blank</code>：通常在<strong>新页签</strong>打开。</li><li><code>Parent</code>：在父浏览上下文中打开。</li><li><code>Self</code>：在当前页面打开。</li><li><code>Top</code>：在顶层浏览上下文中打开。</li></ul></li></ul><h2 id="​-发射信号-signaling-an-event" tabindex="-1"><a href="#signaling-an-event">​</a> 发射信号 (Signaling an Event) <a class="header-anchor" href="#​-发射信号-signaling-an-event" aria-label="Permalink to &quot;[​](#signaling-an-event) 发射信号 (Signaling an Event)&quot;">​</a></h2><p>我们可以通过三种方式触发（发射）事件：通过时间轴、在状态上、或在过渡上。</p><h3 id="​-时间轴-timeline" tabindex="-1"><a href="#timeline">​</a> 时间轴 (Timeline) <a class="header-anchor" href="#​-时间轴-timeline" aria-label="Permalink to &quot;[​](#timeline) 时间轴 (Timeline)&quot;">​</a></h3><p>在时间轴上触发事件允许你控制代码执行的精确时间点（例如配合音效）。 选中目标时间轴，将播放头移至特定时间，点击检查器中的 <strong>“Report Event”</strong> 按钮。</p><blockquote><p><em>[原文档演示图由于官方服务器迁移已失效]</em> (描述: 在时间轴关键帧上报告事件)</p></blockquote><h3 id="​-过渡与状态-transition-state" tabindex="-1"><a href="#transition-&amp;-state">​</a> 过渡与状态 (Transition &amp; State) <a class="header-anchor" href="#​-过渡与状态-transition-state" aria-label="Permalink to &quot;[​](#transition-&amp;-state) 过渡与状态 (Transition &amp; State)&quot;">​</a></h3><p>你可以在<strong>过渡 (Transition)</strong> 或 <strong>状态 (State)</strong> 上报告事件。这通常用于向运行时提供关于状态机所处位置的状态上下文信息。 选中目标状态或过渡，点击检查器中 Events 区域的加号。</p><blockquote><p><em>[原文档演示图由于官方服务器迁移已失效]</em> (描述: 在状态或过渡中报告事件) 下拉菜单允许你选择之前定义的任何事件。你可以决定是在状态/过渡的<strong>开始 (Start)</strong> 还是<strong>结束 (End)</strong> 时发出信号。</p></blockquote><h2 id="​-运行时中的事件" tabindex="-1"><a href="#events-at-runtime">​</a> 运行时中的事件 <a class="header-anchor" href="#​-运行时中的事件" aria-label="Permalink to &quot;[​](#events-at-runtime) 运行时中的事件&quot;">​</a></h2><p>有关如何在运行时监听事件的更多信息，请查阅 <a href="/docs/runtimes/rive-events">Rive 事件 (Runtimes)</a> 章节。</p><p><a href="/docs/editor/state-machine/layers">图层 (Layers)</a><a href="/docs/editor/events/audio-events">音频事件</a></p>',34)])])}const g=a(o,[["render",i]]);export{v as __pageData,g as default};
